package br.com.brindespro.catalog;
import org.springframework.boot.CommandLineRunner;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.util.*;
@Component @ConditionalOnProperty(name="app.demo-data",havingValue="true") public class DemoData implements CommandLineRunner {private final CategoryRepository categories;private final ProductRepository products;public DemoData(CategoryRepository categories,ProductRepository products){this.categories=categories;this.products=products;}@Override @Transactional public void run(String...args){if(categories.count()>0)return;String[][] data={{"Garrafas","garrafas","bottle","Garrafa Térmica Inox 500ml","garrafa-termica-inox-500ml","18.90"},{"Canecas","canecas","mug","Caneca Preta 350ml","caneca-preta-350ml","16.90"},{"Copos","copos","tumbler","Copo Térmico Azul 450ml","copo-termico-azul-450ml","14.90"},{"Canetas","canetas","pens","Caneta Metal","caneta-metal","4.50"},{"Cadernos","cadernos","notebook","Caderno A5","caderno-a5","12.00"},{"Mochilas","mochilas","backpack","Mochila Corporativa","mochila-corporativa","45.00"},{"Kits","kits","kit","Kit Corporativo","kit-corporativo","49.00"}};for(String[] d:data){Category c=categories.save(new Category(d[0],d[1],"/images/products/"+d[2]+".webp"));Product p=new Product(d[3],d[4],c,"/images/products/"+d[2]+".webp");p.description="Personalize com a identidade da sua empresa. Solicite orçamento conforme quantidade e prazo.";p.engravingOptions=d[1].equals("canetas")?"Laser,Tampografia":"Laser,Silk-screen,UV";String material=d[1].equals("canecas")?"Cerâmica":d[1].equals("cadernos")?"Papel":d[1].equals("mochilas")?"Tecido":"Inox";p.variants.add(new ProductVariant(p,"Preto","#17191d",p.imageUrl,material));if(d[1].equals("garrafas")){p.variants.add(new ProductVariant(p,"Azul","#174e91","/images/products/bottle-blue.webp",material));p.variants.add(new ProductVariant(p,"Branco","#f6f6f6","/images/products/bottle-white.webp",material));p.images.add(new ProductImage(p,null,"/images/products/bottle-angle.webp","Garrafa preta em ângulo",1));p.images.add(new ProductImage(p,null,"/images/products/bottle-back.webp","Garrafa preta vista de trás",2));}BigDecimal base=new BigDecimal(d[5]);p.tiers.add(new PricingTier(p,5,49,base.multiply(new BigDecimal("1.25")).setScale(2,java.math.RoundingMode.HALF_UP)));p.tiers.add(new PricingTier(p,50,99,base.multiply(new BigDecimal("1.12")).setScale(2,java.math.RoundingMode.HALF_UP)));p.tiers.add(new PricingTier(p,100,499,base));p.tiers.add(new PricingTier(p,500,999,base.multiply(new BigDecimal("0.93")).setScale(2,java.math.RoundingMode.HALF_UP)));p.tiers.add(new PricingTier(p,1000,null,base.multiply(new BigDecimal("0.88")).setScale(2,java.math.RoundingMode.HALF_UP)));products.save(p);}}}
